package quorma.backend.pack;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.Instant;
import java.util.UUID;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.NoArgsConstructor;
import org.hibernate.annotations.Generated;
import org.hibernate.generator.EventType;

/**
 * One pack bought (immutable row). Its id is the pack id, generated by the server: the origin_ref of the card
 * instances and the reference_id of the ledger row. {@code idempotencyKey} comes from the client and is never used
 * as an identifier on its own, only together with {@code userId}.
 */
@Entity
@Table(name = "pack_openings")
@Getter
@NoArgsConstructor(access = AccessLevel.PROTECTED)
public class PackOpening {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;

    private UUID userId;

    private UUID idempotencyKey;

    private String packType;

    private String faction;

    private UUID snapshotId;

    private long price;

    private long creditsAfter;

    @Generated(event = EventType.INSERT)
    @Column(insertable = false, updatable = false)
    private Instant createdAt;

    public PackOpening(UUID userId, UUID idempotencyKey, String packType, String faction, UUID snapshotId, long price,
                       long creditsAfter) {
        this.userId = userId;
        this.idempotencyKey = idempotencyKey;
        this.packType = packType;
        this.faction = faction;
        this.snapshotId = snapshotId;
        this.price = price;
        this.creditsAfter = creditsAfter;
    }
}
